#[derive(Debug)]
pub struct AyjCodeActionList {
    pub actions: Vec<AyjCodeAction>,
}

impl AyjCodeActionList {
    pub fn new() -> Self { Self { actions: Vec::new() } }
    pub fn add(&mut self, action: AyjCodeAction) { self.actions.push(action); }
    pub fn quickfixes(&self) -> Vec<&AyjCodeAction> { self.actions.iter().filter(|a| a.kind.is_quickfix()).collect() }
    pub fn refactors(&self) -> Vec<&AyjCodeAction> { self.actions.iter().filter(|a| a.kind.is_refactor()).collect() }
    pub fn preferred(&self) -> Option<&AyjCodeAction> { self.actions.iter().find(|a| a.is_preferred) }
    pub fn count(&self) -> usize { self.actions.len() }
}


// --- ayk_ rename provider ---

/// Rename preparation result (validates rename is possible).
#[derive(Debug, Clone)]
pub struct AykPrepareRename {
    pub range_start_line: u32,
    pub range_start_col: u32,
    pub range_end_line: u32,
    pub range_end_col: u32,
    pub placeholder: String,
}

impl AykPrepareRename {
    pub fn new(sl: u32, sc: u32, el: u32, ec: u32, placeholder: &str) -> Self {
        Self { range_start_line: sl, range_start_col: sc, range_end_line: el, range_end_col: ec, placeholder: placeholder.to_string() }
    }
    pub fn is_single_line(&self) -> bool { self.range_start_line == self.range_end_line }
}

/// Rename edit for a single file.
#[derive(Debug, Clone)]
pub struct AykRenameEdit {
    pub uri: String,
    pub start_line: u32,
    pub start_col: u32,
    pub end_line: u32,
    pub end_col: u32,
    pub new_text: String,
}

impl AykRenameEdit {
    pub fn new(uri: &str, sl: u32, sc: u32, el: u32, ec: u32, text: &str) -> Self {
        Self { uri: uri.to_string(), start_line: sl, start_col: sc, end_line: el, end_col: ec, new_text: text.to_string() }
    }
}

/// Workspace-wide rename result.
#[derive(Debug)]
pub struct AykRenameResult {
    pub edits: Vec<AykRenameEdit>,
    pub old_name: String,
    pub new_name: String,
}

impl AykRenameResult {
    pub fn new(old: &str, new_name: &str) -> Self {
        Self { edits: Vec::new(), old_name: old.to_string(), new_name: new_name.to_string() }
    }
    pub fn add(&mut self, edit: AykRenameEdit) { self.edits.push(edit); }
    pub fn edit_count(&self) -> usize { self.edits.len() }
    pub fn file_count(&self) -> usize {
        let mut files: std::collections::HashSet<&str> = std::collections::HashSet::new();
        for e in &self.edits { files.insert(&e.uri); }
        files.len()
    }
    pub fn edits_for_file(&self, uri: &str) -> Vec<&AykRenameEdit> {
        self.edits.iter().filter(|e| e.uri == uri).collect()
    }
    pub fn affected_files(&self) -> Vec<&str> {
        let mut files: Vec<&str> = self.edits.iter().map(|e| e.uri.as_str()).collect();
        files.sort(); files.dedup(); files
    }
    pub fn preview_summary(&self) -> String {
        format!("Rename '{}' -> '{}': {} edits in {} files",
            self.old_name, self.new_name, self.edit_count(), self.file_count())
    }
}

/// Rename validation.
pub struct AykRenameValidator;

impl AykRenameValidator {
    pub fn is_valid_identifier(name: &str) -> bool {
        if name.is_empty() { return false; }
        let first = name.chars().next().unwrap();
        if !first.is_alphabetic() && first != '_' { return false; }
        name.chars().all(|c| c.is_alphanumeric() || c == '_')
    }
    pub fn would_conflict(existing_names: &[&str], new_name: &str) -> bool {
        existing_names.contains(&new_name)
    }
}

/// Rename history for potential undo.
#[derive(Debug)]
pub struct AykRenameHistory {
    pub entries: Vec<AykRenameResult>,
}

impl AykRenameHistory {
    pub fn new() -> Self { Self { entries: Vec::new() } }
    pub fn record(&mut self, result: AykRenameResult) { self.entries.push(result); }
    pub fn last(&self) -> Option<&AykRenameResult> { self.entries.last() }
    pub fn count(&self) -> usize { self.entries.len() }
}


// --- ayl_ document formatting provider ---

/// Formatting options.
#[derive(Debug, Clone)]
pub struct AylFormattingOptions {
    pub tab_size: u32,
    pub insert_spaces: bool,
    pub trim_trailing_whitespace: bool,
    pub insert_final_newline: bool,
    pub trim_final_newlines: bool,
}

impl AylFormattingOptions {
    pub fn default_options() -> Self {
        Self { tab_size: 4, insert_spaces: true, trim_trailing_whitespace: true,
            insert_final_newline: true, trim_final_newlines: true }
    }
    pub fn indent_str(&self) -> String {
        if self.insert_spaces { " ".repeat(self.tab_size as usize) } else { "\t".to_string() }
    }
}

/// A formatting text edit.
#[derive(Debug, Clone)]
pub struct AylFormatEdit {
    pub start_line: u32,
    pub start_col: u32,
    pub end_line: u32,
    pub end_col: u32,
    pub new_text: String,
}

impl AylFormatEdit {
    pub fn new(sl: u32, sc: u32, el: u32, ec: u32, text: &str) -> Self {
        Self { start_line: sl, start_col: sc, end_line: el, end_col: ec, new_text: text.to_string() }
    }
    pub fn whole_document(text: &str, total_lines: u32) -> Self {
        Self { start_line: 0, start_col: 0, end_line: total_lines, end_col: 0, new_text: text.to_string() }
    }
}

/// Formatting result.
#[derive(Debug)]
pub struct AylFormatResult {
    pub edits: Vec<AylFormatEdit>,
}

impl AylFormatResult {
    pub fn new() -> Self { Self { edits: Vec::new() } }
    pub fn add(&mut self, edit: AylFormatEdit) { self.edits.push(edit); }
    pub fn is_empty(&self) -> bool { self.edits.is_empty() }
    pub fn edit_count(&self) -> usize { self.edits.len() }
}

/// Simple whitespace formatter.
pub struct AylWhitespaceFormatter;

impl AylWhitespaceFormatter {
    pub fn format_document(text: &str, opts: &AylFormattingOptions) -> String {
        let mut lines: Vec<String> = text.lines().map(|l| {
            let mut line = l.to_string();
            if opts.trim_trailing_whitespace { line = line.trim_end().to_string(); }
            line
        }).collect();
        if opts.trim_final_newlines {
            while lines.last().map(|l| l.is_empty()).unwrap_or(false) { lines.pop(); }
        }
        let mut result = lines.join("\n");
        if opts.insert_final_newline && !result.ends_with('\n') { result.push('\n'); }
        result
    }
    pub fn format_range(text: &str, start_line: u32, end_line: u32, opts: &AylFormattingOptions) -> Vec<AylFormatEdit> {
        let lines: Vec<&str> = text.lines().collect();
        let mut edits = Vec::new();
        for i in start_line..=end_line.min(lines.len() as u32 - 1) {
            let line = lines[i as usize];
            if opts.trim_trailing_whitespace {
                let trimmed = line.trim_end();
                if trimmed.len() != line.len() {
                    edits.push(AylFormatEdit::new(i, trimmed.len() as u32, i, line.len() as u32, ""));
                }
            }
        }
        edits
    }
}

/// On-type formatting trigger.
#[derive(Debug, Clone)]
pub struct AylOnTypeFormatting {
    pub trigger_characters: Vec<char>,
}

impl AylOnTypeFormatting {
    pub fn new(triggers: Vec<char>) -> Self { Self { trigger_characters: triggers } }
    pub fn should_trigger(&self, c: char) -> bool { self.trigger_characters.contains(&c) }
}


// --- aym_ workspace edit builder and document change application ---

/// A versioned text document identifier.
#[derive(Debug, Clone)]
pub struct AymDocumentId {
    pub uri: String,
    pub version: Option<u32>,
}

impl AymDocumentId {
    pub fn new(uri: &str) -> Self { Self { uri: uri.to_string(), version: None } }
    pub fn versioned(uri: &str, version: u32) -> Self { Self { uri: uri.to_string(), version: Some(version) } }
}

/// A single text change (position + new text).
#[derive(Debug, Clone)]
pub struct AymTextChange {
    pub start_line: u32,
    pub start_col: u32,
    pub end_line: u32,
    pub end_col: u32,
    pub new_text: String,
}

impl AymTextChange {
    pub fn insert(line: u32, col: u32, text: &str) -> Self {
        Self { start_line: line, start_col: col, end_line: line, end_col: col, new_text: text.to_string() }
    }
    pub fn replace(sl: u32, sc: u32, el: u32, ec: u32, text: &str) -> Self {
        Self { start_line: sl, start_col: sc, end_line: el, end_col: ec, new_text: text.to_string() }
    }
    pub fn delete(sl: u32, sc: u32, el: u32, ec: u32) -> Self {
        Self { start_line: sl, start_col: sc, end_line: el, end_col: ec, new_text: String::new() }
    }
    pub fn is_insert(&self) -> bool { self.start_line == self.end_line && self.start_col == self.end_col && !self.new_text.is_empty() }
    pub fn is_delete(&self) -> bool { self.new_text.is_empty() }
}

/// File operation kind.
#[derive(Debug, Clone)]
pub enum AymFileOperation {
    Create { uri: String, overwrite: bool },
    Delete { uri: String, recursive: bool },
    Rename { old_uri: String, new_uri: String, overwrite: bool },
}

impl AymFileOperation {
    pub fn target_uri(&self) -> &str {
        match self { Self::Create { uri, .. } => uri, Self::Delete { uri, .. } => uri, Self::Rename { new_uri, .. } => new_uri }
    }
}

/// Workspace edit builder (fluent API).
#[derive(Debug)]
pub struct AymWorkspaceEditBuilder {
    text_changes: std::collections::HashMap<String, Vec<AymTextChange>>,
    file_ops: Vec<AymFileOperation>,
    label: Option<String>,
}

impl AymWorkspaceEditBuilder {
    pub fn new() -> Self { Self { text_changes: std::collections::HashMap::new(), file_ops: Vec::new(), label: None } }
    pub fn with_label(mut self, label: &str) -> Self { self.label = Some(label.to_string()); self }
    pub fn insert(mut self, uri: &str, line: u32, col: u32, text: &str) -> Self {
        self.text_changes.entry(uri.to_string()).or_default().push(AymTextChange::insert(line, col, text));
        self
    }
    pub fn replace(mut self, uri: &str, sl: u32, sc: u32, el: u32, ec: u32, text: &str) -> Self {
        self.text_changes.entry(uri.to_string()).or_default().push(AymTextChange::replace(sl, sc, el, ec, text));
        self
    }
    pub fn delete_range(mut self, uri: &str, sl: u32, sc: u32, el: u32, ec: u32) -> Self {
        self.text_changes.entry(uri.to_string()).or_default().push(AymTextChange::delete(sl, sc, el, ec));
        self
    }
    pub fn create_file(mut self, uri: &str, overwrite: bool) -> Self {
        self.file_ops.push(AymFileOperation::Create { uri: uri.to_string(), overwrite });
        self
    }
    pub fn delete_file(mut self, uri: &str, recursive: bool) -> Self {
        self.file_ops.push(AymFileOperation::Delete { uri: uri.to_string(), recursive });
        self
    }
    pub fn rename_file(mut self, old: &str, new_uri: &str, overwrite: bool) -> Self {
        self.file_ops.push(AymFileOperation::Rename { old_uri: old.to_string(), new_uri: new_uri.to_string(), overwrite });
        self
    }
    pub fn text_change_count(&self) -> usize { self.text_changes.values().map(|v| v.len()).sum() }
    pub fn file_op_count(&self) -> usize { self.file_ops.len() }
    pub fn affected_files(&self) -> Vec<&str> {
        let mut files: Vec<&str> = self.text_changes.keys().map(|s| s.as_str()).collect();
        files.sort(); files.dedup(); files
    }
    pub fn has_changes(&self) -> bool { !self.text_changes.is_empty() || !self.file_ops.is_empty() }
    pub fn label(&self) -> Option<&str> { self.label.as_deref() }
    pub fn changes_for(&self, uri: &str) -> Vec<&AymTextChange> {
        self.text_changes.get(uri).map(|v| v.iter().collect()).unwrap_or_default()
    }
}


// --- ayn_ terminal input event model ---

/// Mouse button.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AynMouseButton { Left, Right, Middle, ScrollUp, ScrollDown }

/// Mouse event kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AynMouseEventKind { Press, Release, Drag, Move }

/// Mouse event.
#[derive(Debug, Clone, Copy)]
pub struct AynMouseEvent {
    pub button: AynMouseButton,
    pub kind: AynMouseEventKind,
    pub col: u16,
    pub row: u16,
    pub modifiers: u8,
}

impl AynMouseEvent {
    pub fn press(button: AynMouseButton, col: u16, row: u16) -> Self {
        Self { button, kind: AynMouseEventKind::Press, col, row, modifiers: 0 }
    }
    pub fn with_ctrl(mut self) -> Self { self.modifiers |= 1; self }
    pub fn with_shift(mut self) -> Self { self.modifiers |= 2; self }
    pub fn with_alt(mut self) -> Self { self.modifiers |= 4; self }
    pub fn has_ctrl(&self) -> bool { self.modifiers & 1 != 0 }
    pub fn has_shift(&self) -> bool { self.modifiers & 2 != 0 }
    pub fn has_alt(&self) -> bool { self.modifiers & 4 != 0 }
    pub fn is_click(&self) -> bool { self.kind == AynMouseEventKind::Press && matches!(self.button, AynMouseButton::Left | AynMouseButton::Right | AynMouseButton::Middle) }
    pub fn is_scroll(&self) -> bool { matches!(self.button, AynMouseButton::ScrollUp | AynMouseButton::ScrollDown) }
}

/// Terminal resize event.
#[derive(Debug, Clone, Copy)]
pub struct AynResizeEvent {
    pub cols: u16,
    pub rows: u16,
}

impl AynResizeEvent {
    pub fn new(cols: u16, rows: u16) -> Self { Self { cols, rows } }
    pub fn area(&self) -> u32 { self.cols as u32 * self.rows as u32 }
}

/// Paste event.
#[derive(Debug, Clone)]
pub struct AynPasteEvent {
    pub text: String,
}

impl AynPasteEvent {
    pub fn new(text: &str) -> Self { Self { text: text.to_string() } }
    pub fn line_count(&self) -> usize { self.text.lines().count().max(1) }
    pub fn is_multiline(&self) -> bool { self.text.contains('\n') }
}

/// Top-level input event.
#[derive(Debug, Clone)]
pub enum AynInputEvent {
    Key { code: char, ctrl: bool, alt: bool, shift: bool },
    FunctionKey(u8),
    Special(AynSpecialKey),
    Mouse(AynMouseEvent),
    Resize(AynResizeEvent),
    Paste(AynPasteEvent),
    FocusGained,
    FocusLost,
}

/// Special (non-character) keys.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AynSpecialKey {
    Enter, Escape, Tab, Backspace, Delete, Home, End,
    PageUp, PageDown, Up, Down, Left, Right, Insert,
}

impl AynInputEvent {
    pub fn is_key(&self) -> bool { matches!(self, Self::Key { .. }) }
    pub fn is_mouse(&self) -> bool { matches!(self, Self::Mouse(_)) }
    pub fn is_resize(&self) -> bool { matches!(self, Self::Resize(_)) }
}

/// Input event queue.
#[derive(Debug)]
pub struct AynEventQueue {
    events: std::collections::VecDeque<AynInputEvent>,
    capacity: usize,
}

impl AynEventQueue {
    pub fn new(capacity: usize) -> Self {
        Self { events: std::collections::VecDeque::new(), capacity }
    }
    pub fn push(&mut self, event: AynInputEvent) {
        if self.events.len() >= self.capacity { self.events.pop_front(); }
        self.events.push_back(event);
    }
    pub fn pop(&mut self) -> Option<AynInputEvent> { self.events.pop_front() }
    pub fn peek(&self) -> Option<&AynInputEvent> { self.events.front() }
    pub fn len(&self) -> usize { self.events.len() }
    pub fn is_empty(&self) -> bool { self.events.is_empty() }
    pub fn clear(&mut self) { self.events.clear(); }
}


// --- ayo_ panel layout and view containers ---

/// Panel position.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AyoPanelPosition { Bottom, Left, Right }

/// Sidebar position.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AyoSidebarPosition { Left, Right }

/// Layout region.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AyoLayoutRegion { Editor, Sidebar, Panel, ActivityBar, StatusBar }

/// Rectangle for layout.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AyoRect { pub x: u16, pub y: u16, pub width: u16, pub height: u16 }

impl AyoRect {
    pub fn new(x: u16, y: u16, w: u16, h: u16) -> Self { Self { x, y, width: w, height: h } }
    pub fn area(&self) -> u32 { self.width as u32 * self.height as u32 }
    pub fn contains(&self, col: u16, row: u16) -> bool {
        col >= self.x && col < self.x + self.width && row >= self.y && row < self.y + self.height
    }
    pub fn right(&self) -> u16 { self.x + self.width }
    pub fn bottom(&self) -> u16 { self.y + self.height }
}

/// View container.
#[derive(Debug, Clone)]
pub struct AyoViewContainer {
    pub id: String,
    pub title: String,
    pub views: Vec<String>,
    pub is_visible: bool,
}

impl AyoViewContainer {
    pub fn new(id: &str, title: &str) -> Self {
        Self { id: id.to_string(), title: title.to_string(), views: Vec::new(), is_visible: true }
    }
    pub fn add_view(&mut self, view_id: &str) { self.views.push(view_id.to_string()); }
    pub fn view_count(&self) -> usize { self.views.len() }
}

/// Editor layout manager.
#[derive(Debug)]
pub struct AyoLayout {
    pub total_cols: u16,
    pub total_rows: u16,
    pub sidebar_visible: bool,
    pub sidebar_position: AyoSidebarPosition,
    pub sidebar_width: u16,
    pub panel_visible: bool,
    pub panel_position: AyoPanelPosition,
    pub panel_height: u16,
    pub activity_bar_visible: bool,
    pub status_bar_visible: bool,
}

impl AyoLayout {
    pub fn new(cols: u16, rows: u16) -> Self {
        Self {
            total_cols: cols, total_rows: rows,
            sidebar_visible: true, sidebar_position: AyoSidebarPosition::Left, sidebar_width: 30,
            panel_visible: true, panel_position: AyoPanelPosition::Bottom, panel_height: 10,
            activity_bar_visible: true, status_bar_visible: true,
        }
    }
    pub fn toggle_sidebar(&mut self) { self.sidebar_visible = !self.sidebar_visible; }
    pub fn toggle_panel(&mut self) { self.panel_visible = !self.panel_visible; }
    pub fn editor_rect(&self) -> AyoRect {
        let ab_w: u16 = if self.activity_bar_visible { 2 } else { 0 };
        let sb_w: u16 = if self.sidebar_visible { self.sidebar_width } else { 0 };
        let status_h: u16 = if self.status_bar_visible { 1 } else { 0 };
        let panel_h: u16 = if self.panel_visible && self.panel_position == AyoPanelPosition::Bottom { self.panel_height } else { 0 };
        let x = ab_w + if self.sidebar_position == AyoSidebarPosition::Left { sb_w } else { 0 };
        let w = self.total_cols - ab_w - sb_w;
        let h = self.total_rows - status_h - panel_h;
        AyoRect::new(x, 0, w, h)
    }
    pub fn sidebar_rect(&self) -> Option<AyoRect> {
        if !self.sidebar_visible { return None; }
        let ab_w: u16 = if self.activity_bar_visible { 2 } else { 0 };
        let x = if self.sidebar_position == AyoSidebarPosition::Left { ab_w } else { self.total_cols - self.sidebar_width };
        let status_h: u16 = if self.status_bar_visible { 1 } else { 0 };
        Some(AyoRect::new(x, 0, self.sidebar_width, self.total_rows - status_h))
    }
    pub fn panel_rect(&self) -> Option<AyoRect> {
        if !self.panel_visible { return None; }
        let status_h: u16 = if self.status_bar_visible { 1 } else { 0 };
        let y = self.total_rows - status_h - self.panel_height;
        let ab_w: u16 = if self.activity_bar_visible { 2 } else { 0 };
        Some(AyoRect::new(ab_w, y, self.total_cols - ab_w, self.panel_height))
    }
    pub fn resize(&mut self, cols: u16, rows: u16) { self.total_cols = cols; self.total_rows = rows; }
    pub fn region_at(&self, col: u16, row: u16) -> AyoLayoutRegion {
        if self.status_bar_visible && row == self.total_rows - 1 { return AyoLayoutRegion::StatusBar; }
        if self.activity_bar_visible && col < 2 { return AyoLayoutRegion::ActivityBar; }
        if let Some(r) = self.sidebar_rect() { if r.contains(col, row) { return AyoLayoutRegion::Sidebar; } }
        if let Some(r) = self.panel_rect() { if r.contains(col, row) { return AyoLayoutRegion::Panel; } }
        AyoLayoutRegion::Editor
    }
}


// --- ayp_ clipboard and selection model ---

/// Selection direction.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AypSelectionDirection { LeftToRight, RightToLeft }

/// A text selection range.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AypSelection {
    pub anchor_line: u32,
    pub anchor_col: u32,
    pub active_line: u32,
    pub active_col: u32,
}

impl AypSelection {
    pub fn new(al: u32, ac: u32, sl: u32, sc: u32) -> Self {
        Self { anchor_line: al, anchor_col: ac, active_line: sl, active_col: sc }
    }
    pub fn cursor(line: u32, col: u32) -> Self { Self::new(line, col, line, col) }
    pub fn is_empty(&self) -> bool { self.anchor_line == self.active_line && self.anchor_col == self.active_col }
    pub fn direction(&self) -> AypSelectionDirection {
        if self.active_line < self.anchor_line || (self.active_line == self.anchor_line && self.active_col < self.anchor_col) {
            AypSelectionDirection::RightToLeft
        } else { AypSelectionDirection::LeftToRight }
    }
    pub fn start(&self) -> (u32, u32) {
        if self.direction() == AypSelectionDirection::LeftToRight { (self.anchor_line, self.anchor_col) }
        else { (self.active_line, self.active_col) }
    }
    pub fn end(&self) -> (u32, u32) {
        if self.direction() == AypSelectionDirection::LeftToRight { (self.active_line, self.active_col) }
        else { (self.anchor_line, self.anchor_col) }
    }
    pub fn contains_line(&self, line: u32) -> bool {
        let (sl, _) = self.start();
        let (el, _) = self.end();
        line >= sl && line <= el
    }
    pub fn line_count(&self) -> u32 {
        let (sl, _) = self.start();
        let (el, _) = self.end();
        el - sl + 1
    }
    pub fn collapse_to_active(&self) -> Self { Self::cursor(self.active_line, self.active_col) }
    pub fn reverse(&self) -> Self { Self::new(self.active_line, self.active_col, self.anchor_line, self.anchor_col) }
}

/// Selection kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AypSelectionKind { Normal, Line, Block }

/// Clipboard content type.
#[derive(Debug, Clone)]
pub enum AypClipboardContent {
    Text(String),
    Lines(Vec<String>),
    Block(Vec<String>),
}

impl AypClipboardContent {
    pub fn text(s: &str) -> Self { Self::Text(s.to_string()) }
    pub fn as_text(&self) -> String {
        match self {
            Self::Text(s) => s.clone(),
            Self::Lines(v) => v.join("\n"),
            Self::Block(v) => v.join("\n"),
        }
    }
    pub fn line_count(&self) -> usize {
        match self {
            Self::Text(s) => s.lines().count().max(1),
            Self::Lines(v) | Self::Block(v) => v.len(),
        }
    }
    pub fn is_empty(&self) -> bool {
        match self { Self::Text(s) => s.is_empty(), Self::Lines(v) | Self::Block(v) => v.is_empty() }
    }
}

/// Clipboard with history.
#[derive(Debug)]
pub struct AypClipboard {
    pub history: Vec<AypClipboardContent>,
    pub max_history: usize,
}

impl AypClipboard {
    pub fn new(max_history: usize) -> Self { Self { history: Vec::new(), max_history } }
    pub fn copy(&mut self, content: AypClipboardContent) {
        self.history.push(content);
        if self.history.len() > self.max_history { self.history.remove(0); }
    }
    pub fn paste(&self) -> Option<&AypClipboardContent> { self.history.last() }
    pub fn paste_nth(&self, n: usize) -> Option<&AypClipboardContent> {
        if n < self.history.len() { Some(&self.history[self.history.len() - 1 - n]) } else { None }
    }
    pub fn history_count(&self) -> usize { self.history.len() }
    pub fn clear(&mut self) { self.history.clear(); }
}


// --- ayq_ editor zooming and font scaling ---

/// Zoom level (percentage-based).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct AyqZoomLevel {
    pub percentage: f32,
}

impl AyqZoomLevel {
    pub const DEFAULT: Self = Self { percentage: 100.0 };
    pub const MIN: f32 = 50.0;
    pub const MAX: f32 = 300.0;
    pub const STEP: f32 = 10.0;

    pub fn new(pct: f32) -> Self { Self { percentage: pct.clamp(Self::MIN, Self::MAX) } }
    pub fn zoom_in(&self) -> Self { Self::new(self.percentage + Self::STEP) }
    pub fn zoom_out(&self) -> Self { Self::new(self.percentage - Self::STEP) }
    pub fn reset(&self) -> Self { Self::DEFAULT }
    pub fn scale_factor(&self) -> f32 { self.percentage / 100.0 }
    pub fn is_default(&self) -> bool { (self.percentage - 100.0).abs() < 0.01 }
    pub fn apply_to(&self, value: u32) -> u32 { (value as f32 * self.scale_factor()).round() as u32 }
}

/// Font size configuration.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct AyqFontSize {
    pub base_size: f32,
    pub line_height_ratio: f32,
    pub letter_spacing: f32,
}

impl AyqFontSize {
    pub fn new(base: f32) -> Self { Self { base_size: base, line_height_ratio: 1.5, letter_spacing: 0.0 } }
    pub fn with_line_height(mut self, ratio: f32) -> Self { self.line_height_ratio = ratio; self }
    pub fn effective_size(&self, zoom: &AyqZoomLevel) -> f32 { self.base_size * zoom.scale_factor() }
    pub fn line_height(&self, zoom: &AyqZoomLevel) -> f32 { self.effective_size(zoom) * self.line_height_ratio }
    pub fn terminal_cols_for_width(&self, width_px: u32, zoom: &AyqZoomLevel) -> u32 {
        let char_width = self.effective_size(zoom) * 0.6 + self.letter_spacing;
        if char_width <= 0.0 { return 80; }
        (width_px as f32 / char_width).floor() as u32
    }
}

/// Editor zoom state.
#[derive(Debug)]
pub struct AyqZoomState {
    pub editor_zoom: AyqZoomLevel,
    pub terminal_zoom: AyqZoomLevel,
    pub font: AyqFontSize,
    pub zoom_per_editor: std::collections::HashMap<String, AyqZoomLevel>,
}

impl AyqZoomState {
    pub fn new(font_size: f32) -> Self {
        Self {
            editor_zoom: AyqZoomLevel::DEFAULT, terminal_zoom: AyqZoomLevel::DEFAULT,
            font: AyqFontSize::new(font_size), zoom_per_editor: std::collections::HashMap::new(),
        }
    }
    pub fn zoom_in(&mut self) { self.editor_zoom = self.editor_zoom.zoom_in(); }
    pub fn zoom_out(&mut self) { self.editor_zoom = self.editor_zoom.zoom_out(); }
    pub fn reset_zoom(&mut self) { self.editor_zoom = AyqZoomLevel::DEFAULT; }
    pub fn effective_font_size(&self) -> f32 { self.font.effective_size(&self.editor_zoom) }
    pub fn effective_line_height(&self) -> f32 { self.font.line_height(&self.editor_zoom) }
    pub fn set_editor_zoom(&mut self, uri: &str, zoom: AyqZoomLevel) {
        self.zoom_per_editor.insert(uri.to_string(), zoom);
    }
    pub fn editor_zoom_for(&self, uri: &str) -> AyqZoomLevel {
        self.zoom_per_editor.get(uri).copied().unwrap_or(self.editor_zoom)
    }
}


// --- ayr_ integrated terminal session model ---

/// Terminal profile.
#[derive(Debug, Clone)]
pub struct AyrTerminalProfile {
    pub name: String,
    pub shell_path: String,
    pub shell_args: Vec<String>,
    pub env: std::collections::HashMap<String, String>,
    pub cwd: Option<String>,
    pub icon: Option<String>,
}

impl AyrTerminalProfile {
    pub fn new(name: &str, shell: &str) -> Self {
        Self { name: name.to_string(), shell_path: shell.to_string(), shell_args: Vec::new(),
            env: std::collections::HashMap::new(), cwd: None, icon: None }
    }
    pub fn with_args(mut self, args: Vec<String>) -> Self { self.shell_args = args; self }
    pub fn with_cwd(mut self, cwd: &str) -> Self { self.cwd = Some(cwd.to_string()); self }
}

/// Terminal session state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AyrTerminalState { Starting, Running, Exited(i32) }

/// A terminal session.
#[derive(Debug)]
pub struct AyrTerminalSession {
    pub id: u32,
    pub name: String,
    pub profile: AyrTerminalProfile,
    pub state: AyrTerminalState,
    pub scroll_back_lines: Vec<String>,
    pub visible_lines: Vec<String>,
    pub cursor_row: u32,
    pub cursor_col: u32,
    pub cols: u16,
    pub rows: u16,
}

impl AyrTerminalSession {
    pub fn new(id: u32, profile: AyrTerminalProfile) -> Self {
        let name = profile.name.clone();
        Self { id, name, profile, state: AyrTerminalState::Starting,
            scroll_back_lines: Vec::new(), visible_lines: Vec::new(),
            cursor_row: 0, cursor_col: 0, cols: 80, rows: 24 }
    }
    pub fn start(&mut self) { self.state = AyrTerminalState::Running; }
    pub fn exit(&mut self, code: i32) { self.state = AyrTerminalState::Exited(code); }
    pub fn is_running(&self) -> bool { self.state == AyrTerminalState::Running }
    pub fn is_exited(&self) -> bool { matches!(self.state, AyrTerminalState::Exited(_)) }
    pub fn write_line(&mut self, line: &str) {
        self.visible_lines.push(line.to_string());
        if self.visible_lines.len() > self.rows as usize {
            let removed = self.visible_lines.remove(0);
            self.scroll_back_lines.push(removed);
        }
    }
    pub fn resize(&mut self, cols: u16, rows: u16) { self.cols = cols; self.rows = rows; }
    pub fn total_lines(&self) -> usize { self.scroll_back_lines.len() + self.visible_lines.len() }
    pub fn clear(&mut self) {
        self.scroll_back_lines.extend(self.visible_lines.drain(..));
    }
}

/// Terminal session manager.
#[derive(Debug)]
pub struct AyrTerminalManager {
    pub sessions: Vec<AyrTerminalSession>,
    pub active_id: Option<u32>,
    pub next_id: u32,
    pub default_profile: AyrTerminalProfile,
}

impl AyrTerminalManager {
    pub fn new(default_profile: AyrTerminalProfile) -> Self {
        Self { sessions: Vec::new(), active_id: None, next_id: 1, default_profile }
    }
    pub fn create_session(&mut self, profile: Option<AyrTerminalProfile>) -> u32 {
        let id = self.next_id;
        self.next_id += 1;
        let p = profile.unwrap_or_else(|| self.default_profile.clone());
        let mut session = AyrTerminalSession::new(id, p);
        session.start();
        self.sessions.push(session);
        self.active_id = Some(id);
        id
    }
    pub fn active_session(&self) -> Option<&AyrTerminalSession> {
        self.active_id.and_then(|id| self.sessions.iter().find(|s| s.id == id))
    }
    pub fn active_session_mut(&mut self) -> Option<&mut AyrTerminalSession> {
        let id = self.active_id?;
        self.sessions.iter_mut().find(|s| s.id == id)
    }
    pub fn set_active(&mut self, id: u32) { if self.sessions.iter().any(|s| s.id == id) { self.active_id = Some(id); } }
    pub fn session_count(&self) -> usize { self.sessions.len() }
    pub fn running_count(&self) -> usize { self.sessions.iter().filter(|s| s.is_running()).count() }
    pub fn remove_exited(&mut self) { self.sessions.retain(|s| !s.is_exited()); }
}


// --- ays_ extension contribution points ---

/// Contribution point kind.
