    // ---- Fenwick tree tests — crate 88 ----

    #[test]
    fn xn_88_fenwick_prefix_sum() {
        let mut ft = super::Xn88Fenwick::xn_new(5);
        for i in 0..5 { ft.xn_update(i, (i + 1) as i64); }
        assert_eq!(ft.xn_prefix_sum(0), 1);
        assert_eq!(ft.xn_prefix_sum(4), 15);
    }

    #[test]
    fn xn_88_fenwick_range_sum() {
        let mut ft = super::Xn88Fenwick::xn_new(6);
        for i in 0..6 { ft.xn_update(i, (i * 2) as i64); }
        assert_eq!(ft.xn_range_sum(1, 3), 2 + 4 + 6);
    }

    #[test]
    fn xn_88_fenwick_point_query() {
        let mut ft = super::Xn88Fenwick::xn_new(4);
        ft.xn_update(2, 7);
        assert_eq!(ft.xn_point_query(2), 7);
        assert_eq!(ft.xn_point_query(0), 0);
    }

    #[test]
    fn xn_88_fenwick_len() {
        let ft = super::Xn88Fenwick::xn_new(10);
        assert_eq!(ft.xn_len(), 10);
    }

