    fn test_yw_future_map() {
        let f = YwFuture::ready(5);
        let g = f.map(|x| x * 2);
        assert_eq!(g.value(), Some(&10));
    }

    #[test]
    fn test_yw_future_flat_map() {
        let f = YwFuture::ready(5);
        let g = f.flat_map(|x| YwFuture::ready(x + 1));
        assert_eq!(g.value(), Some(&6));
    }

