    // --- axf_ extension host process tests ---

    #[test]
    fn test_axf_host_state() {
        assert!(AxfHostState::Running.is_running());
        assert!(AxfHostState::Starting.is_alive());
        assert!(!AxfHostState::Crashed.is_alive());
    }

    #[test]
    fn test_axf_ipc_message() {
        let req = AxfIpcMessage::request(1, "activate", "{}");
        assert!(req.is_request());
        let resp = AxfIpcMessage::success(1, "ok");
        assert!(resp.is_response());
        let evt = AxfIpcMessage::event("change", "{}");
        assert!(evt.is_event());
    }

    #[test]
    fn test_axf_ipc_channel() {
        let mut ch = AxfIpcChannel::new();
        let id = ch.send_request("activate", "{}");
        assert_eq!(id, 1);
        ch.send_event("changed", "{}");
        assert_eq!(ch.pending_outgoing(), 2);
        let msgs = ch.drain_outgoing();
        assert_eq!(msgs.len(), 2);
        assert_eq!(ch.pending_outgoing(), 0);
    }

    #[test]
    fn test_axf_ipc_channel_incoming() {
        let mut ch = AxfIpcChannel::new();
        ch.receive(AxfIpcMessage::success(1, "result"));
        assert_eq!(ch.pending_incoming(), 1);
        let msgs = ch.drain_incoming();
        assert_eq!(msgs.len(), 1);
    }

    #[test]
    fn test_axf_extension_host_lifecycle() {
        let mut host = AxfExtensionHost::new("local-1", AxfHostKind::Local);
        assert_eq!(host.state, AxfHostState::NotStarted);
        host.start(1234, 1000);
        assert_eq!(host.state, AxfHostState::Starting);
        assert_eq!(host.pid, Some(1234));
        host.mark_ready();
        assert!(host.state.is_running());
        assert_eq!(host.uptime(2000), Some(1000));
        host.crash();
        assert_eq!(host.state, AxfHostState::Crashed);
        assert!(host.should_restart());
    }

    #[test]
    fn test_axf_extension_host_extensions() {
        let mut host = AxfExtensionHost::new("h1", AxfHostKind::Local);
        host.register_extension("ext.a");
        host.register_extension("ext.b");
        host.register_extension("ext.a"); // duplicate
        assert_eq!(host.extension_count(), 2);
    }

    #[test]
    fn test_axf_extension_host_crash_limit() {
        let mut host = AxfExtensionHost::new("h", AxfHostKind::Local);
        host.crash();
        assert!(host.should_restart());
        host.crash();
        assert!(host.should_restart());
        host.crash();
        assert!(!host.should_restart()); // 3 crashes, no more restarts
    }

    #[test]
    fn test_axf_host_manager() {
        let mut mgr = AxfHostManager::new();
        let idx = mgr.create_host("local", AxfHostKind::Local);
        mgr.host_mut(idx).unwrap().start(100, 0);
        mgr.host_mut(idx).unwrap().mark_ready();
        mgr.host_mut(idx).unwrap().register_extension("ext.a");
        assert_eq!(mgr.running_hosts().len(), 1);
        assert_eq!(mgr.total_extensions(), 1);
        assert_eq!(mgr.find_host_for_extension("ext.a"), Some(0));
        assert_eq!(mgr.find_host_for_extension("ext.z"), None);
    }

    #[test]
    fn test_axf_host_manager_terminate_all() {
        let mut mgr = AxfHostManager::new();
        let i1 = mgr.create_host("a", AxfHostKind::Local);
        let i2 = mgr.create_host("b", AxfHostKind::Remote);
        mgr.host_mut(i1).unwrap().start(1, 0);
        mgr.host_mut(i1).unwrap().mark_ready();
        mgr.host_mut(i2).unwrap().start(2, 0);
        mgr.host_mut(i2).unwrap().mark_ready();
        mgr.terminate_all();
        assert!(mgr.running_hosts().is_empty());
    }


    // --- axg_ file watcher tests ---

    #[test]
    fn test_axg_fs_event_types() {
        let c = AxgFsEvent::created("/a.rs", 100, false);
        assert_eq!(c.kind, AxgFsEventKind::Created);
        assert!(!c.is_directory);
        let r = AxgFsEvent::renamed("/old.rs", "/new.rs", 200);
        assert_eq!(r.kind, AxgFsEventKind::Renamed);
        assert_eq!(r.old_path.as_deref(), Some("/old.rs"));
    }

    #[test]
    fn test_axg_watch_pattern_simple() {
        let p = AxgWatchPattern::new("/project", "*.rs");
        assert!(p.matches("/project/src/main.rs"));
        assert!(!p.matches("/project/src/main.py"));
        assert!(!p.matches("/other/main.rs"));
    }

    #[test]
    fn test_axg_watch_pattern_exclude() {
        let p = AxgWatchPattern::new("/project", "**").exclude("node_modules");
        assert!(p.matches("/project/src/main.rs"));
        assert!(!p.matches("/project/node_modules/x.js"));
    }

    #[test]
    fn test_axg_watch_pattern_non_recursive() {
        let p = AxgWatchPattern::new("/project", "*.rs").non_recursive();
        assert!(p.matches("/project/main.rs"));
        assert!(!p.matches("/project/src/main.rs"));
    }

    #[test]
    fn test_axg_file_watcher() {
        let mut fw = AxgFileWatcher::new(100);
        let id = fw.watch(AxgWatchPattern::new("/src", "*.rs"));
        assert_eq!(fw.subscription_count(), 1);
        assert_eq!(fw.active_count(), 1);
        let matching = fw.matching_subscriptions("/src/lib.rs");
        assert_eq!(matching, vec![id]);
        assert!(fw.matching_subscriptions("/src/lib.py").is_empty());
    }

    #[test]
    fn test_axg_file_watcher_events() {
        let mut fw = AxgFileWatcher::new(50);
        fw.push_event(AxgFsEvent::changed("/a.rs", 1));
        fw.push_event(AxgFsEvent::created("/b.rs", 2, false));
        let events = fw.drain_events();
        assert_eq!(events.len(), 2);
        assert!(fw.drain_events().is_empty());
    }

    #[test]
    fn test_axg_file_watcher_unwatch() {
        let mut fw = AxgFileWatcher::new(50);
        let id = fw.watch(AxgWatchPattern::new("/x", "*"));
        assert!(fw.unwatch(id));
        assert_eq!(fw.subscription_count(), 0);
        assert!(!fw.unwatch(id)); // already removed
    }

    #[test]
    fn test_axg_file_watcher_pause_resume() {
        let mut fw = AxgFileWatcher::new(50);
        let id = fw.watch(AxgWatchPattern::new("/x", "*"));
        fw.pause_subscription(id);
        assert_eq!(fw.active_count(), 0);
        assert!(fw.matching_subscriptions("/x/a").is_empty());
        fw.resume_subscription(id);
        assert_eq!(fw.active_count(), 1);
    }


    // --- axh_ output channel and logging tests ---

    #[test]
    fn test_axh_log_level_ordering() {
        assert!(AxhLogLevel::Error > AxhLogLevel::Warning);
        assert!(AxhLogLevel::Warning > AxhLogLevel::Info);
        assert!(AxhLogLevel::Info > AxhLogLevel::Debug);
        assert!(AxhLogLevel::Debug > AxhLogLevel::Trace);
    }

    #[test]
    fn test_axh_output_channel_basic() {
        let mut ch = AxhOutputChannel::new("Test");
        ch.append_line("Hello");
        ch.append_line("World");
        assert_eq!(ch.line_count(), 2);
        assert_eq!(ch.content(), "Hello\nWorld");
        ch.clear();
        assert_eq!(ch.line_count(), 0);
    }

    #[test]
    fn test_axh_output_channel_append() {
        let mut ch = AxhOutputChannel::new("T");
        ch.append("Hello ");
        ch.append("World");
        assert_eq!(ch.line_count(), 1);
        assert_eq!(ch.lines()[0], "Hello World");
    }

    #[test]
    fn test_axh_output_channel_logging() {
        let mut ch = AxhOutputChannel::new("Log");
        ch.log_level = AxhLogLevel::Info;
        ch.trace("should skip");
        ch.debug("should skip");
        ch.info("visible");
        ch.warn("visible");
        ch.error("visible");
        assert_eq!(ch.line_count(), 3);
    }

    #[test]
    fn test_axh_output_channel_visibility() {
        let mut ch = AxhOutputChannel::new("V");
        assert!(!ch.is_visible);
        ch.show();
        assert!(ch.is_visible);
        ch.hide();
        assert!(!ch.is_visible);
    }

    #[test]
    fn test_axh_log_channel() {
        let ch = AxhOutputChannel::log_channel("LSP", "json");
        assert!(ch.is_log_channel);
        assert_eq!(ch.language_id.as_deref(), Some("json"));
    }

    #[test]
    fn test_axh_output_channel_replace() {
        let mut ch = AxhOutputChannel::new("R");
        ch.append_line("old");
        ch.replace("new");
        assert_eq!(ch.line_count(), 1);
        assert_eq!(ch.lines()[0], "new");
    }

    #[test]
    fn test_axh_output_registry() {
        let mut reg = AxhOutputRegistry::new();
        let i1 = reg.create("Output");
        let i2 = reg.create_log("LSP Log", "json");
        assert_eq!(reg.channel_count(), 2);
        assert_eq!(reg.channel_names(), vec!["Output", "LSP Log"]);
        reg.set_active(i1);
        assert!(reg.active_channel().unwrap().is_visible);
        reg.set_active(i2);
        assert!(!reg.get(i1).unwrap().is_visible);
        assert!(reg.get(i2).unwrap().is_visible);
    }

    #[test]
    fn test_axh_output_registry_find() {
        let mut reg = AxhOutputRegistry::new();
        reg.create("MyChannel");
        assert_eq!(reg.find_by_name("MyChannel"), Some(0));
        assert_eq!(reg.find_by_name("Other"), None);
    }

    #[test]
    fn test_axh_output_registry_dispose() {
        let mut reg = AxhOutputRegistry::new();
        reg.create("A");
        reg.create("B");
        assert!(reg.dispose(0));
        assert_eq!(reg.channel_count(), 1);
        assert_eq!(reg.channel_names(), vec!["B"]);
    }


