        p.add_entry(BezTimelineEntry::new("c1", "First", BezTimelineEntryType::GitCommit, 100));
        p.add_entry(BezTimelineEntry::new("c2", "Second", BezTimelineEntryType::GitCommit, 200));
        let sorted = p.sorted_entries();
